// Idempotency & Duplicate Check against memory / database store
const pkg = $input.first().json;

// Simulate database check
const dedupKey = `${pkg.candidate_id}_${pkg.job_id}`;
const appliedDatabase = new Set(); // in-memory mock store

if (appliedDatabase.has(dedupKey)) {
  return [{
    json: {
      schema_version: '1.0',
      application_id: 'app_' + Date.now(),
      candidate_id: pkg.candidate_id,
      job_id: pkg.job_id,
      company: pkg.company,
      job_title: pkg.job_title,
      approval_decision: 'REVIEW',
      application_status: 'skipped_duplicate',
      submission_method: 'mock',
      submitted_at: null,
      attempts: 0,
      confirmation_sent: false,
      error: null
    }
  }];
}

return [{ json: { package: pkg, dedupKey: dedupKey } }];

// Human Approval Gate simulation (Can be replaced by n8n Form / Email buttons)
const input = $input.first().json;
const pkg = input.package;

// Simulated Approval decision: 'APPROVED'
const approvalDecision = 'APPROVED';

return [{
  json: {
    ...input,
    approval_decision: approvalDecision
  }
}];

// Submission execution, persistence, and Contract 3.5 status output
const input = $input.first().json;
const pkg = input.package;
const decision = input.approval_decision;

let status = 'pending_approval';
let submittedAt = null;
let confirmationSent = false;

if (decision === 'APPROVED') {
  status = 'submitted';
  submittedAt = new Date().toISOString();
  confirmationSent = true; // Email notification sent with PDF attachments
} else if (decision === 'REJECTED') {
  status = 'failed';
}

const statusPayload = {
  schema_version: '1.0',
  application_id: 'app_' + Date.now(),
  candidate_id: pkg.candidate_id,
  job_id: pkg.job_id,
  company: pkg.company,
  job_title: pkg.job_title,
  approval_decision: decision,
  application_status: status,
  submission_method: 'mock',
  submitted_at: submittedAt,
  attempts: 1,
  confirmation_sent: confirmationSent,
  error: null
};

return [{ json: statusPayload }];
